-- Agreement v2: spell out the fee-on-top model, refunds and disputes. The fee percent is not written
-- into the text because it lives in game_settings; the post form and job screens show the exact amount.
-- Users accept the new version before their next job.
UPDATE marketplace_agreements SET is_current = false WHERE is_current AND kind IN ('cleaner', 'customer');

INSERT INTO marketplace_agreements (kind, version, title, body, is_current) VALUES
  ('cleaner', 2, 'Cleaner agreement and liability waiver (draft)',
   E'DRAFT FOR LEGAL REVIEW. Not final wording.\n\n1. Independent contractor. You are not an employee or agent of Frontline. You choose which jobs to take, set your own rates, and decide how to do the work.\n2. Assumption of risk. Cleanup work is physical and can cause injury. You accept those risks and release Frontline from claims for injury or property damage arising from jobs you take, to the extent the law allows.\n3. Safety rules. Do not handle hazardous waste, sharps, biohazards or unknown chemicals. Do not enter confined or unsafe spaces. Do not work alone at night. Stop and leave if a site is unsafe.\n4. Your responsibilities. You provide your own tools and protective gear, and you are responsible for your taxes and any local licences.\n5. Conduct. Be honest, respectful and on time. No harassment, theft or off-platform payment.\n6. Age. You confirm you are at least 18.\n7. Payment. The customer pays the posted job price plus a service fee. You receive the full posted price. Payment is held by Frontline when you accept and is sent to your bank through Stripe after the customer confirms the work, or automatically after the review period if there is no dispute. Jobs posted before the service fee change may deduct a platform fee from your price, and the job screen shows which applies.\n8. Cancellations and disputes. If a job is cancelled before work starts, the customer is refunded in full. If there is a dispute, payment stays held while Frontline reviews photos and messages, and Frontline decides the outcome.\n9. Payout setup. You must finish Stripe payout setup before taking jobs.\n10. Changes. If these terms change you must accept the new version before taking more jobs.',
   true),
  ('customer', 2, 'Customer terms (draft)',
   E'DRAFT FOR LEGAL REVIEW. Not final wording.\n\n1. Authority. You have the right to authorize work on the property you describe.\n2. Accuracy. Describe the site and job honestly and disclose any known hazards.\n3. No hazardous materials. Do not request work involving hazardous waste, sharps, biohazards or anything needing a licence.\n4. Payment and fee. You pay the posted job price plus a service fee. The exact total is shown before you post and on the job. Your card is charged when a cleaner accepts, and the money is held by Frontline. It is released to the cleaner when you confirm the job, or automatically after the review period if there is no dispute.\n5. Cancellations and refunds. You can cancel until work starts and your card is refunded in full. After work starts, open a dispute instead.\n6. Disputes. If you report a problem, payment stays held while Frontline reviews photos and messages, and Frontline decides the outcome.\n7. Venue. Frontline is a venue that connects you with independent cleaners and is not the contractor or employer.\n8. Changes. If these terms change you must accept the new version before posting more jobs.',
   true);
